UPDATE gallery_photos SET src = '[{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1792843207/gujarat-post/gallery/gallery_006bf00d-0f0c-438c-bca6-74224a1bbd5e.jpg\",\"title\":\"ઉર્ફી જાવેદનો હોટ અવતાર દેખાયો\",\"caption\":\"અભિનેત્રી ઉર્ફી જાવેદે તેના નવા ફોટોમાં બધી જ હદો વટાવી દીધી છે. તેના નવા વાઇરલ થયેલા ફોટો તેના લાખો ચાહકો પસંદ કરી રહ્યાં છે, અગાઉ પણ ઉર્ફીના અનેક હોટ ફોટો વાઇરલ થયા હતા.\",\"captionGu\":\"ઉર્ફી જાવેદનો હોટ અવતાર દેખાયો\",\"description\":\"અભિનેત્રી ઉર્ફી જાવેદે તેના નવા ફોટોમાં બધી જ હદો વટાવી દીધી છે. તેના નવા વાઇરલ થયેલા ફોટો તેના લાખો ચાહકો પસંદ કરી રહ્યાં છે, અગાઉ પણ ઉર્ફીના અનેક હોટ ફોટો વાઇરલ થયા હતા.\",\"photographer\":\"Gujarat Post\"},{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1793093408/gujarat-post/gallery/gallery_006bf00d-0f0c-438c-bca6-74224a1bbd5e_slide_1.jpg\",\"title\":\"ઉર્ફી જાવેદનો હોટ અવતાર દેખાયો\",\"caption\":\"અભિનેત્રી ઉર્ફી જાવેદે તેના નવા ફોટોમાં બધી જ હદો વટાવી દીધી છે. તેના નવા વાઇરલ થયેલા ફોટો તેના લાખો ચાહકો પસંદ કરી રહ્યાં છે, અગાઉ પણ ઉર્ફીના અનેક હોટ ફોટો વાઇરલ થયા હતા.\",\"captionGu\":\"ઉર્ફી જાવેદનો હોટ અવતાર દેખાયો\",\"description\":\"અભિનેત્રી ઉર્ફી જાવેદે તેના નવા ફોટોમાં બધી જ હદો વટાવી દીધી છે. તેના નવા વાઇરલ થયેલા ફોટો તેના લાખો ચાહકો પસંદ કરી રહ્યાં છે, અગાઉ પણ ઉર્ફીના અનેક હોટ ફોટો વાઇરલ થયા હતા.\",\"photographer\":\"Gujarat Post\"}]', updatedAt = NOW() WHERE id = '006bf00d-0f0c-438c-bca6-74224a1bbd5e';
