UPDATE gallery_photos SET src = '[{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1792843229/gujarat-post/gallery/gallery_0b37cc83-8a6d-4a3c-9410-525af05c71e9.jpg\",\"title\":\"સલમાન-કેટરિનાની ફિલ્મ ભારતના પ્રિમિયર પર કેટરિનાનો હસીન અંદાજ \",\"caption\":\"સુપરસ્ટાર સલમાન ખાન અને કેટરિના કૈફની ફિલ્મ ભારત ઇદના દિવસે રિલિઝ થઇ છે તે અગાઉ મુંબઇમાં ફિલ્મના પ્રિમિયરમાં કેટરિના કૈફ બ્લેક ડ્રેસમાં પહોંચી હતી, ફિલ્મને લઇને તે ઘણી ઉત્સાહમાં દેખાતી હતી\",\"captionGu\":\"સલમાન-કેટરિનાની ફિલ્મ ભારતના પ્રિમિયર પર કેટરિનાનો હસીન અંદાજ \",\"description\":\"સુપરસ્ટાર સલમાન ખાન અને કેટરિના કૈફની ફિલ્મ ભારત ઇદના દિવસે રિલિઝ થઇ છે તે અગાઉ મુંબઇમાં ફિલ્મના પ્રિમિયરમાં કેટરિના કૈફ બ્લેક ડ્રેસમાં પહોંચી હતી, ફિલ્મને લઇને તે ઘણી ઉત્સાહમાં દેખાતી હતી\",\"photographer\":\"Gujarat Post\"},{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1793093312/gujarat-post/gallery/gallery_0b37cc83-8a6d-4a3c-9410-525af05c71e9_slide_1.jpg\",\"title\":\"સલમાન-કેટરિનાની ફિલ્મ ભારતના પ્રિમિયર પર કેટરિનાનો હસીન અંદાજ \",\"caption\":\"સુપરસ્ટાર સલમાન ખાન અને કેટરિના કૈફની ફિલ્મ ભારત ઇદના દિવસે રિલિઝ થઇ છે તે અગાઉ મુંબઇમાં ફિલ્મના પ્રિમિયરમાં કેટરિના કૈફ બ્લેક ડ્રેસમાં પહોંચી હતી, ફિલ્મને લઇને તે ઘણી ઉત્સાહમાં દેખાતી હતી\",\"captionGu\":\"સલમાન-કેટરિનાની ફિલ્મ ભારતના પ્રિમિયર પર કેટરિનાનો હસીન અંદાજ \",\"description\":\"સુપરસ્ટાર સલમાન ખાન અને કેટરિના કૈફની ફિલ્મ ભારત ઇદના દિવસે રિલિઝ થઇ છે તે અગાઉ મુંબઇમાં ફિલ્મના પ્રિમિયરમાં કેટરિના કૈફ બ્લેક ડ્રેસમાં પહોંચી હતી, ફિલ્મને લઇને તે ઘણી ઉત્સાહમાં દેખાતી હતી\",\"photographer\":\"Gujarat Post\"}]', updatedAt = NOW() WHERE id = '0b37cc83-8a6d-4a3c-9410-525af05c71e9';
