UPDATE gallery_photos SET src = '[{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1792843432/gujarat-post/gallery/gallery_515e7f8b-c4a5-46b8-a1a9-40e082925130.jpg\",\"title\":\"મલાઈકા અરોરાનો મોહક અંદાજ\",\"caption\":\"મલાઈકા અરોરા બોલીવુડની સુંદરીઓમાંની એક છે જે પોતાની ફિટનેસ તેમજ સ્ટાઇલિશ સેન્સ માટે જાણીતી છે. અભિનેત્રીએ પોતાની ફેશનથી સાબિત કરી દીધું છે કે ફિટ બોડી સાથે બોલ્ડનેસને કેવી રીતે બેલેન્સ કરવી. અભિનેત્રી એક શોમાં રેડ કલરનું સેક્સી ગાઉન પહેરીને પહોંચી હતી.\",\"captionGu\":\"મલાઈકા અરોરાનો મોહક અંદાજ\",\"description\":\"મલાઈકા અરોરા બોલીવુડની સુંદરીઓમાંની એક છે જે પોતાની ફિટનેસ તેમજ સ્ટાઇલિશ સેન્સ માટે જાણીતી છે. અભિનેત્રીએ પોતાની ફેશનથી સાબિત કરી દીધું છે કે ફિટ બોડી સાથે બોલ્ડનેસને કેવી રીતે બેલેન્સ કરવી. અભિનેત્રી એક શોમાં રેડ કલરનું સેક્સી ગાઉન પહેરીને પહોંચી હતી.\",\"photographer\":\"Gujarat Post\"},{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1793093402/gujarat-post/gallery/gallery_515e7f8b-c4a5-46b8-a1a9-40e082925130_slide_1.jpg\",\"title\":\"મલાઈકા અરોરાનો મોહક અંદાજ\",\"caption\":\"મલાઈકા અરોરા બોલીવુડની સુંદરીઓમાંની એક છે જે પોતાની ફિટનેસ તેમજ સ્ટાઇલિશ સેન્સ માટે જાણીતી છે. અભિનેત્રીએ પોતાની ફેશનથી સાબિત કરી દીધું છે કે ફિટ બોડી સાથે બોલ્ડનેસને કેવી રીતે બેલેન્સ કરવી. અભિનેત્રી એક શોમાં રેડ કલરનું સેક્સી ગાઉન પહેરીને પહોંચી હતી.\",\"captionGu\":\"મલાઈકા અરોરાનો મોહક અંદાજ\",\"description\":\"મલાઈકા અરોરા બોલીવુડની સુંદરીઓમાંની એક છે જે પોતાની ફિટનેસ તેમજ સ્ટાઇલિશ સેન્સ માટે જાણીતી છે. અભિનેત્રીએ પોતાની ફેશનથી સાબિત કરી દીધું છે કે ફિટ બોડી સાથે બોલ્ડનેસને કેવી રીતે બેલેન્સ કરવી. અભિનેત્રી એક શોમાં રેડ કલરનું સેક્સી ગાઉન પહેરીને પહોંચી હતી.\",\"photographer\":\"Gujarat Post\"}]', updatedAt = NOW() WHERE id = '515e7f8b-c4a5-46b8-a1a9-40e082925130';
