UPDATE gallery_photos SET src = '[{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1792843476/gujarat-post/gallery/gallery_6166b4dc-e8b0-4b66-ac9c-5c152afe3137.jpg\",\"title\":\"અભિનેત્રી આલિયાનું બાથટબમાં ફોટોશુટ \",\"caption\":\"લાખો દિલોની ધડકન એવી આલિયા ભટ્ટના નવા ફોટો સામે આવ્યાં છે, આ વખતે તેને બાથટબમાં ફોટોશુટ કરાવ્યું છે. તેના લાખો ચાહકો આ ફોટોને પસંદ કરી રહ્યાં છે\",\"captionGu\":\"અભિનેત્રી આલિયાનું બાથટબમાં ફોટોશુટ \",\"description\":\"લાખો દિલોની ધડકન એવી આલિયા ભટ્ટના નવા ફોટો સામે આવ્યાં છે, આ વખતે તેને બાથટબમાં ફોટોશુટ કરાવ્યું છે. તેના લાખો ચાહકો આ ફોટોને પસંદ કરી રહ્યાં છે\",\"photographer\":\"Gujarat Post\"},{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1793093407/gujarat-post/gallery/gallery_6166b4dc-e8b0-4b66-ac9c-5c152afe3137_slide_1.jpg\",\"title\":\"અભિનેત્રી આલિયાનું બાથટબમાં ફોટોશુટ \",\"caption\":\"લાખો દિલોની ધડકન એવી આલિયા ભટ્ટના નવા ફોટો સામે આવ્યાં છે, આ વખતે તેને બાથટબમાં ફોટોશુટ કરાવ્યું છે. તેના લાખો ચાહકો આ ફોટોને પસંદ કરી રહ્યાં છે\",\"captionGu\":\"અભિનેત્રી આલિયાનું બાથટબમાં ફોટોશુટ \",\"description\":\"લાખો દિલોની ધડકન એવી આલિયા ભટ્ટના નવા ફોટો સામે આવ્યાં છે, આ વખતે તેને બાથટબમાં ફોટોશુટ કરાવ્યું છે. તેના લાખો ચાહકો આ ફોટોને પસંદ કરી રહ્યાં છે\",\"photographer\":\"Gujarat Post\"}]', updatedAt = NOW() WHERE id = '6166b4dc-e8b0-4b66-ac9c-5c152afe3137';
