UPDATE gallery_photos SET src = '[{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1792843630/gujarat-post/gallery/gallery_8a389f5f-6f87-4ef1-b9bf-7917901d2055.jpg\",\"title\":\" મુંબઇમાં એવોર્ડ ફંક્શનમાં જ્હાન્વી કપૂરનો બોલ્ડ અંદાજ \",\"caption\":\"મુંબઇમાં યોજાયેલા હેલો, હોલ ઓફ ફેમ એવોર્ડ ફંક્શનમાં સૌ કૌઇની નજર જ્હાન્વી કપૂર પર હતી, નવા જ અંદાજમાં શ્રીદેવીની પુત્રી જ્હાન્વી જોવા મળી હતી, તેના ચાહકોએ પણ તેને જોઇને ખુશ ખુશાલ થઇ ગયા હતા.\",\"captionGu\":\" મુંબઇમાં એવોર્ડ ફંક્શનમાં જ્હાન્વી કપૂરનો બોલ્ડ અંદાજ \",\"description\":\"મુંબઇમાં યોજાયેલા હેલો, હોલ ઓફ ફેમ એવોર્ડ ફંક્શનમાં સૌ કૌઇની નજર જ્હાન્વી કપૂર પર હતી, નવા જ અંદાજમાં શ્રીદેવીની પુત્રી જ્હાન્વી જોવા મળી હતી, તેના ચાહકોએ પણ તેને જોઇને ખુશ ખુશાલ થઇ ગયા હતા.\",\"photographer\":\"Gujarat Post\"},{\"src\":\"https://res.cloudinary.com/kohg6a5j/image/upload/v1793093210/gujarat-post/gallery/gallery_8a389f5f-6f87-4ef1-b9bf-7917901d2055_slide_1.jpg\",\"title\":\" મુંબઇમાં એવોર્ડ ફંક્શનમાં જ્હાન્વી કપૂરનો બોલ્ડ અંદાજ \",\"caption\":\"મુંબઇમાં યોજાયેલા હેલો, હોલ ઓફ ફેમ એવોર્ડ ફંક્શનમાં સૌ કૌઇની નજર જ્હાન્વી કપૂર પર હતી, નવા જ અંદાજમાં શ્રીદેવીની પુત્રી જ્હાન્વી જોવા મળી હતી, તેના ચાહકોએ પણ તેને જોઇને ખુશ ખુશાલ થઇ ગયા હતા.\",\"captionGu\":\" મુંબઇમાં એવોર્ડ ફંક્શનમાં જ્હાન્વી કપૂરનો બોલ્ડ અંદાજ \",\"description\":\"મુંબઇમાં યોજાયેલા હેલો, હોલ ઓફ ફેમ એવોર્ડ ફંક્શનમાં સૌ કૌઇની નજર જ્હાન્વી કપૂર પર હતી, નવા જ અંદાજમાં શ્રીદેવીની પુત્રી જ્હાન્વી જોવા મળી હતી, તેના ચાહકોએ પણ તેને જોઇને ખુશ ખુશાલ થઇ ગયા હતા.\",\"photographer\":\"Gujarat Post\"}]', updatedAt = NOW() WHERE id = '8a389f5f-6f87-4ef1-b9bf-7917901d2055';
